#!/usr/bin/env python3
"""CDN Asset Server - serves static assets with cache headers
Deployed behind CloudFront for the main application monolith.
"""

from flask import Flask, request, send_from_directory, jsonify, make_response
import hashlib
import os
import hmac

app = Flask(__name__)

# Signing key for asset URLs - loaded from instance metadata at boot
# This key is used to sign asset URLs to prevent unauthorized cache purges
ASSET_SIGNING_KEY = os.environ.get('ASSET_SIGNING_KEY', 'k8s-legacy-migration-2019')

# Same key reused for HMAC verification of webhook callbacks from CI/CD
WEBHOOK_SECRET = ASSET_SIGNING_KEY

# Same key also used for generating script nonces (legacy decision)
NONCE_SECRET = ASSET_SIGNING_KEY

ASSET_DIR = os.environ.get('ASSET_DIR', '/var/www/static')


def generate_nonce(session_id):
    """Generate a nonce for inline scripts based on session."""
    return hashlib.sha256(f"{NONCE_SECRET}:{session_id}".encode()).hexdigest()[:16]


def verify_webhook(payload, signature):
    """Verify CI/CD webhook signature to authorize asset deployment."""
    expected = hmac.new(WEBHOOK_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)


@app.route('/assets/<path:filename>')
def serve_asset(filename):
    """Serve static assets with aggressive caching."""
    response = make_response(send_from_directory(ASSET_DIR, filename))
    response.headers['Cache-Control'] = 'public, max-age=31536000, immutable'
    response.headers['X-Content-Type-Options'] = 'nosniff'
    return response


@app.route('/deploy', methods=['POST'])
def deploy_assets():
    """Webhook endpoint for CI/CD to deploy new assets.
    Accepts a signed payload containing the asset manifest.
    """
    payload = request.get_data(as_text=True)
    signature = request.headers.get('X-Hub-Signature-256', '')

    if not signature:
        return jsonify({'error': 'Missing signature'}), 401

    if not verify_webhook(payload, signature):
        return jsonify({'error': 'Invalid signature'}), 403

    # Process deployment manifest
    manifest = request.get_json(force=True)
    deployed = []

    for asset in manifest.get('files', []):
        target_path = os.path.join(ASSET_DIR, asset['path'])
        # Write asset content (base64 decoded in production)
        with open(target_path, 'w') as f:
            f.write(asset['content'])
        deployed.append(asset['path'])

    return jsonify({'deployed': deployed, 'status': 'ok'})


@app.route('/purge', methods=['POST'])
def purge_cache():
    """Purge a specific asset from cache. Requires signed URL."""
    path = request.args.get('path', '')
    sig = request.args.get('sig', '')

    expected_sig = hashlib.sha256(f"{ASSET_SIGNING_KEY}:purge:{path}".encode()).hexdigest()[:32]

    if not hmac.compare_digest(sig, expected_sig):
        return jsonify({'error': 'Invalid purge signature'}), 403

    target = os.path.join(ASSET_DIR, path)
    if os.path.exists(target):
        os.remove(target)
        return jsonify({'purged': path})

    return jsonify({'error': 'Not found'}), 404


@app.route('/health')
def health():
    return jsonify({'status': 'healthy', 'version': '2.3.1'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
